   335	fn scan_name(source:&[u8],scan:&mut NameScan,limit:usize,qname:bool,work:&mut NameWork)->Result<Option<NameParts>,(XmlError,usize)>{
   336	    while scan.pos<limit&&scan.pos<source.len(){
   337	        let p=scan.pos;
   338	        let byte=work.read(source,p);
   339	        // ASCII delimiters terminate a name without consuming their byte. A
   340	        // multibyte scalar is decoded incrementally from its saved state.
   341	        if !scan.utf8.incomplete()&&byte<0x80 {
   342	            let allowed=if p==scan.start{is_name_start(u32::from(byte))}else{is_name_char(u32::from(byte))};
   343	            if !allowed {if p==scan.start{return Err((XmlError::InvalidName,p))}break}
   344	        }
   345	        let decoded=work.decode(&mut scan.utf8,byte,p).map_err(|at|(XmlError::InvalidUtf8,at))?;
   346	        scan.pos+=1;
   347	        if scan.pos-scan.start>MAX_TOKEN_NAME_BYTES{return Err((XmlError::MalformedSyntax,scan.start))}
   348	        let Some(cp)=decoded else{continue};
   349	        let at=scan.utf8.start;let first=at==scan.start;
   350	        if !(if first{is_name_start(cp)}else{is_name_char(cp)}) {
   351	            if first{return Err((XmlError::InvalidName,at))}
   352	            scan.pos=at;break
   353	        }
   354	        if first{scan.leading_colon=cp==b':' as u32}
   355	        if let Some(colon)=scan.first_colon {
   356	            if at==colon+1{scan.local_first_valid=Some(is_name_start(cp))}
   357	        }
   358	        if cp==b':' as u32 {
   359	            if qname&&scan.first_colon.is_some(){return Err((XmlError::InvalidName,scan.first_colon.unwrap_or(at)))}
   360	            if scan.first_colon.is_none(){scan.first_colon=Some(at)}
   361	        }
   362	        scan.trailing_colon=cp==b':' as u32;
   363	    }
   364	    let p=scan.pos;
   365	    if p==source.len()&&scan.utf8.incomplete(){return Err((XmlError::InvalidUtf8,scan.utf8.start))}
