     5	fn budget_one_name_scans_measure_real_source_reads_and_decoder_inputs() {
     6	    for (scalar, width) in [("é", 2), ("中", 3), ("𐀀", 4)] {
     7	        let source = format!("<p:{scalar} {scalar}='x'><?{scalar} x?></p:{scalar}>");
     8	        let (expected, result) = tokenize(source.as_bytes(), XmlLimits::default());
     9	        assert_eq!(result.diagnostic, XmlDiagnostic::default());
    10	        let mut stream = XmlTokenStream::new(source.as_bytes(), 16 * size_of::<XmlToken>()).unwrap();
    11	        for _ in 0..source.len() { assert_eq!(stream.step(1, false), StreamStatus::Ok); }
    12	        assert!(stream.chars_complete);
    13	        assert_eq!(stream.name_work.reads, 0);
    14	        assert_eq!(stream.name_work.decoder_inputs, 0);
    15	        let mut complete = false;
    16	        for _ in 0..source.len() * 3 + 64 {
    17	            let reads = stream.name_work.reads;
    18	            let inputs = stream.name_work.decoder_inputs;
    19	            let status = stream.step(1, false);
    20	            let actual_reads = stream.name_work.reads - reads;
    21	            let actual_inputs = stream.name_work.decoder_inputs - inputs;
    22	            assert!(actual_reads <= 1, "width={width}, actual name reads={actual_reads}");
    23	            assert!(actual_inputs <= actual_reads);
    24	            if status == StreamStatus::Complete { complete = true; break; }
    25	            assert_eq!(status, StreamStatus::Ok);
    26	        }
    27	        assert!(complete);
    28	        // Four multibyte names, two ASCII "p:" prefixes, and four delimiter
    29	        // probes. These are counts of actual loads/pushes, not cursor deltas.
    30	        assert_eq!(stream.name_work.decoder_inputs, 4 * width + 4);
    31	        assert_eq!(stream.name_work.reads, 4 * width + 8);
    32	        assert_eq!(stream.result(), result);
    33	        assert_eq!(stream.take().unwrap(), expected);
    34	    }
    35	}
