    72	fn finish(stream: &mut XmlTokenStream<'_>, budget: usize) -> StreamStatus {
    73	    for _ in 0..stream.source.len().saturating_mul(3).saturating_add(64) {
    74	        let scanned = stream.char_cursor;
    75	        let parsed = stream.bytes_read();
    76	        let status = stream.step(budget, false);
    77	        assert!(stream.char_cursor.saturating_sub(scanned)
    78	            + stream.bytes_read().saturating_sub(parsed) <= budget.min(STEP_CAP));
    79	        if status != StreamStatus::Ok { return status; }
    80	    }
    81	    panic!("stream stalled at scan={} parse={}", stream.char_cursor, stream.bytes_read());
    82	}
