   129	#[test]
   130	fn cancellation_can_interrupt_each_partial_utf8_scalar_between_bytes() {
   131	    for scalar in ["é", "中", "😀"] {
   132	        let source = format!("<r>{scalar}</r>");
   133	        for consumed in 1..scalar.len() {
   134	            let mut stepped = XmlTokenStream::new(source.as_bytes(), 16 * size_of::<XmlToken>()).unwrap();
   135	            for byte in 1..=3 + consumed {
   136	                assert_eq!(stepped.step(1, false), StreamStatus::Ok);
   137	                assert_eq!(stepped.char_cursor, byte);
   138	            }
   139	            assert!(stepped.utf8.incomplete());
   140	            assert_eq!(stepped.step(1, true), StreamStatus::Canceled);
   141	            assert_eq!(stepped.char_cursor, 3 + consumed);
   142	            assert_empty_result(&mut stepped, XmlDiagnostic::default());
   143	            let mut stream = XmlTokenStream::new(source.as_bytes(), 16 * size_of::<XmlToken>()).unwrap();
   144	            let mut polls = 0;
   145	            let mut cancel = || { polls += 1; polls > 1 + 3 + consumed };
   146	            assert_eq!(stream.step_with_cancel(64, &mut cancel), StreamStatus::Canceled);
   147	            assert_eq!(stream.char_cursor, 3 + consumed);
   148	            assert_eq!(stream.utf8.start, 3);
   149	            assert!(stream.utf8.incomplete());
   150	            assert_empty_result(&mut stream, XmlDiagnostic::default());
   151	            assert_eq!(stream.step(1, false), StreamStatus::Canceled);
   152	        }
   153	    }
   154	}
