   162	        (&[0xe0, 0x80, 0x80], false, XmlError::InvalidUtf8),
   163	        (&[0xed, 0xa0, 0x80], false, XmlError::InvalidUtf8),
   164	        (&[0xe2, 0x82, b'A'], false, XmlError::InvalidUtf8),
   165	        (&[0xe2, 0x82], true, XmlError::InvalidUtf8),
   166	        (&[0xf0, 0x80, 0x80, 0x80], false, XmlError::InvalidUtf8),
   167	        (&[0xf4, 0x90, 0x80, 0x80], false, XmlError::InvalidUtf8),
   168	        (&[0xf0, 0x90, 0x80, b'A'], false, XmlError::InvalidUtf8),
