   191	#[test]
   192	fn batch_cancelable_apis_cancel_inside_long_lexical_parsing_after_validation() {
   193	    for (prefix, suffix) in [
   194	        (b"<r>".as_slice(), b"</r>".as_slice()),
   195	        (b"<r v='".as_slice(), b"'/>".as_slice()),
   196	        (b"<r><!--".as_slice(), b"--></r>".as_slice()),
   197	        (b"<r><![CDATA[".as_slice(), b"]]></r>".as_slice()),
   198	        (b"<r><?p ".as_slice(), b"?></r>".as_slice()),
   199	        (b"<!DOCTYPE r SYSTEM '".as_slice(), b"'><r/>".as_slice()),
   200	    ] {
   201	        let mut source = prefix.to_vec(); source.extend(std::iter::repeat_n(b'x', 256 * 1024)); source.extend_from_slice(suffix);
   202	        let threshold = source.len() + 2048;
   203	        let mut stream = XmlTokenStream::new(&source, 16 * size_of::<XmlToken>()).unwrap();
   204	        let mut polls = 0;
   205	        let mut cancel = || { polls += 1; polls == threshold };
   206	        loop { let status = stream.step_with_cancel(STEP_CAP, &mut cancel); if status != StreamStatus::Ok { assert_eq!(status, StreamStatus::Canceled); break; } }
   207	        assert!(stream.chars_complete);
   208	        assert_eq!(stream.char_cursor, source.len());
   209	        assert!(stream.bytes_read() > prefix.len());
   210	        assert!(stream.bytes_read() < source.len());
   211	        assert_empty_result(&mut stream, XmlDiagnostic::default());
   212	        for large in [false, true] {
   213	            let mut polls = 0;
   214	            let cancel = || { polls += 1; polls == threshold };
   215	            let (tokens, result, status) = if large { tokenize_large_cancelable(&source, 16, cancel) }
   216	                else { tokenize_cancelable(&source, XmlLimits::default(), 16, cancel) };
   217	            assert_eq!(status, StreamStatus::Canceled);
   218	            assert_eq!(polls, threshold);
   219	            assert!(tokens.is_empty()); assert_eq!(result, XmlResult::default());
   220	        }
   221	    }
   222	}
